/* ============================================
   ShiftWise — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --accent: #DE5052;
  --accent-dark: #c23d3f;
  --white: #FFFFFF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --radius: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --max-width: 1200px;
  --transition: all 0.2s ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Container */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: var(--shadow);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--gray-700);
  border: 1.5px solid var(--gray-300);
}

.btn-outline:hover {
  border-color: var(--gray-400);
  background: var(--gray-50);
}

.btn-white {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow);
}

.btn-white:hover {
  background: var(--gray-50);
  transform: translateY(-1px);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1rem;
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
}

.header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
  letter-spacing: -0.03em;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 0.875rem;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-desktop a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
}

.nav-desktop a:hover {
  color: var(--gray-900);
}

.nav-desktop .btn {
  margin-left: 0.5rem;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: var(--transition);
}

.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(15,23,42,0.4);
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
}

.mobile-nav.active {
  opacity: 1;
  visibility: visible;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: min(320px, 85vw);
  height: 100%;
  background: var(--white);
  padding: 1.5rem;
  transform: translateX(100%);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
}

.mobile-nav.active .mobile-nav-panel {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.mobile-nav-close {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  color: var(--gray-500);
}

.mobile-nav-close:hover {
  background: var(--gray-100);
  color: var(--gray-900);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
}

.mobile-nav-links a {
  padding: 0.875rem 1rem;
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius);
  transition: var(--transition);
}

.mobile-nav-links a:hover {
  background: var(--gray-50);
  color: var(--gray-900);
}

.mobile-nav-cta {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.mobile-nav-cta .btn {
  width: 100%;
}

/* Hero */
.hero {
  position: relative;
  padding: 5rem 0;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--gray-50) 0%, var(--white) 50%, #eff6ff 100%);
  z-index: -1;
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,81,195,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-content {
  max-width: 560px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.375rem 1rem;
  background: rgba(0,81,195,0.08);
  color: var(--primary);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 999px;
  margin-bottom: 1.5rem;
}

.hero-title {
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image {
  width: 100%;
  max-width: 560px;
  aspect-ratio: 4/3;
  background: linear-gradient(145deg, var(--primary) 0%, #1e6fdb 100%);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 4rem;
  position: relative;
  overflow: hidden;
}

.hero-image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

/* Section Header */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 3.5rem;
}

.section-header h2 {
  margin-bottom: 0.75rem;
}

.section-header p {
  font-size: 1.125rem;
}

/* Features Grid */
.features {
  padding: 5rem 0;
  background: var(--white);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.feature-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: var(--transition);
}

.feature-card:hover {
  border-color: var(--gray-300);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  background: rgba(0,81,195,0.08);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.25rem;
}

.feature-card h3 {
  margin-bottom: 0.5rem;
  font-size: 1.125rem;
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* How It Works */
.how-it-works {
  padding: 5rem 0;
  background: var(--gray-50);
}

.steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.step {
  position: relative;
  text-align: center;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 auto 1.25rem;
}

.step h3 {
  margin-bottom: 0.5rem;
  font-size: 1.125rem;
}

.step p {
  font-size: 0.9375rem;
  color: var(--gray-500);
}

/* Testimonials */
.testimonials {
  padding: 5rem 0;
  background: var(--white);
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-track {
  overflow: hidden;
}

.testimonial-slides {
  display: flex;
  transition: transform 0.4s ease;
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 1rem;
}

.testimonial-card {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  text-align: center;
  border: 1px solid var(--gray-200);
}

.testimonial-quote {
  font-size: 1.25rem;
  color: var(--gray-700);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 1.5rem;
}

.testimonial-author {
  font-weight: 600;
  color: var(--gray-900);
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.testimonial-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.testimonial-nav button {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  color: var(--gray-600);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.testimonial-nav button:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(0,81,195,0.04);
}

.testimonial-dots {
  display: flex;
  gap: 0.5rem;
}

.testimonial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: var(--transition);
}

.testimonial-dot.active {
  background: var(--primary);
  width: 24px;
  border-radius: 4px;
}

/* Stats */
.stats {
  padding: 4rem 0;
  background: var(--primary);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-number {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.75);
}

/* Pricing */
.pricing {
  padding: 5rem 0;
  background: var(--gray-50);
}

.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.pricing-toggle-label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  cursor: pointer;
}

.pricing-toggle-label.active {
  color: var(--gray-900);
  font-weight: 600;
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 999px;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform 0.2s ease;
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  padding: 2rem;
  transition: var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}

.pricing-badge {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.375rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
}

.pricing-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 1.25rem;
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
}

.pricing-price .currency {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--gray-900);
}

.pricing-price .amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--gray-900);
  line-height: 1;
}

.pricing-price .period {
  font-size: 0.9375rem;
  color: var(--gray-500);
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.9375rem;
  color: var(--gray-600);
}

.pricing-features li .icon-check {
  color: var(--primary);
  flex-shrink: 0;
}

.pricing-features li .icon-dash {
  color: var(--gray-400);
  flex-shrink: 0;
}

.pricing-features li.missing {
  color: var(--gray-400);
}

.pricing-card .btn {
  width: 100%;
}

/* Pricing Table (detailed) */
.pricing-table-section {
  padding: 5rem 0;
  background: var(--white);
}

.pricing-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.pricing-table th,
.pricing-table td {
  padding: 1rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-table th {
  font-weight: 600;
  color: var(--gray-900);
  background: var(--gray-50);
}

.pricing-table th:first-child {
  border-radius: var(--radius) 0 0 0;
}

.pricing-table th:last-child {
  border-radius: 0 var(--radius) 0 0;
}

.pricing-table td {
  color: var(--gray-600);
}

.pricing-table tr:hover td {
  background: var(--gray-50);
}

/* FAQ */
.faq {
  padding: 5rem 0;
  background: var(--gray-50);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: var(--transition);
}

.faq-item.active {
  border-color: var(--gray-300);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-900);
  text-align: left;
}

.faq-question svg {
  flex-shrink: 0;
  transition: transform 0.2s ease;
  color: var(--gray-500);
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
  color: var(--primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding: 0 1.5rem 1.25rem;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* CTA Section */
.cta-section {
  padding: 5rem 0;
  background: linear-gradient(135deg, var(--primary) 0%, #0046aa 100%);
  color: var(--white);
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 0.75rem;
}

.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 2rem;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.cta-section .btn-accent {
  background: var(--accent);
}

.cta-section .btn-accent:hover {
  background: var(--accent-dark);
}

/* Feature Detail */
.feature-detail {
  padding: 5rem 0;
}

.feature-detail:nth-child(even) {
  background: var(--gray-50);
}

.feature-detail .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail.reverse .container {
  direction: rtl;
}

.feature-detail.reverse .container > * {
  direction: ltr;
}

.feature-detail-visual {
  aspect-ratio: 4/3;
  background: linear-gradient(145deg, var(--primary) 0%, #1e6fdb 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 3.5rem;
  box-shadow: var(--shadow-lg);
  position: relative;
  overflow: hidden;
}

.feature-detail-visual::before {
  content: '';
  position: absolute;
  inset: 0;
